// Find the shortest walking route through a small square-tile map.
// grid-pathfinding: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [width, height, start_cell, goal_cell, ...row_major_grid]
// Output: [...path_cell_ids] or [] if unreachable
// Cell ID is y*width+x; zero tiles are walkable. BFS with equal-cost four-neighbor movement.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#![allow(unused_assignments, unused_mut, dead_code, unused_parens)]
// Count how many numbers are in this list.
fn port_length(a: &[f64]) -> f64 { a.len() as f64 }
// Read one number at a zero-based position; stop if that position does not exist.
fn port_get(a: &[f64], i:f64) -> f64 { assert!(i.is_finite() && i>=0.0 && i.fract()==0.0 && i<(a.len() as f64)); a[i as usize] }
// Replace a number at an existing position in the list.
fn port_put(i:f64, v:f64, a: &mut Vec<f64>) { port_get(a,i); a[i as usize]=v; }
// Add one number to the end of the list.
fn port_push(v:f64, a: &mut Vec<f64>) { a.push(v); }
// Round down to a whole number; minus 0.1 becomes minus 1.
fn port_floor_num(a:f64)->f64 { a.floor() }

// 1. Start on the player tile and put it in a waiting line.
// 2. Check nearby tiles: right, left, down, and up. Skip walls and already checked tiles.
// 3. Remember which tile led to each new tile.
// 4. When the target is found, follow those memories backward and reverse them to get the route.
pub fn compute(data: &[f64]) -> Vec<f64> {
    let mut w: f64 = 0.0;
    let mut h: f64 = 0.0;
    let mut start: f64 = 0.0;
    let mut goal: f64 = 0.0;
    let mut n: f64 = 0.0;
    let mut parent: Vec<f64> = Vec::new();
    let mut queue: Vec<f64> = Vec::new();
    let mut i: f64 = 0.0;
    let mut head: f64 = 0.0;
    let mut reverse: Vec<f64> = Vec::new();
    let mut cell: f64 = 0.0;
    let mut result: Vec<f64> = Vec::new();
    let mut x: f64 = 0.0;
    let mut y: f64 = 0.0;
    let mut direction: f64 = 0.0;
    let mut nx: f64 = 0.0;
    let mut ny: f64 = 0.0;
    let mut other: f64 = 0.0;
    w = port_get(&data, 0.0);
    h = port_get(&data, 1.0);
    start = port_get(&data, 2.0);
    goal = port_get(&data, 3.0);
    n = (w * h);
    if ((w < 1.0) || (h < 1.0) || (start < 0.0) || (goal < 0.0) || (start >= n) || (goal >= n) || (port_length(&data) != (n + 4.0))) {
        return vec![];
    }
    if ((port_get(&data, (4.0 + start)) != 0.0) || (port_get(&data, (4.0 + goal)) != 0.0)) {
        return vec![];
    }
    parent = vec![];
    queue = vec![start];
    i = 0.0;
    while (i < n) {
        port_push(-(1.0), &mut parent);
        i += 1.0;
    }
    port_put(start, start, &mut parent);
    head = 0.0;
    while (head < port_length(&queue)) {
        cell = port_get(&queue, head);
        head += 1.0;
        if (cell == goal) {
            break;
        }
        x = (cell - (w * port_floor_num((cell / w))));
        y = port_floor_num((cell / w));
        direction = 0.0;
        while (direction < 4.0) {
            nx = x;
            ny = y;
            if (direction == 0.0) {
                nx += 1.0;
            }
            if (direction == 1.0) {
                nx -= 1.0;
            }
            if (direction == 2.0) {
                ny += 1.0;
            }
            if (direction == 3.0) {
                ny -= 1.0;
            }
            other = ((ny * w) + nx);
            if ((nx >= 0.0) && (nx < w) && (ny >= 0.0) && (ny < h)) {
                if ((port_get(&parent, other) == -(1.0)) && (port_get(&data, (4.0 + other)) == 0.0)) {
                    port_put(other, cell, &mut parent);
                    port_push(other, &mut queue);
                }
            }
            direction += 1.0;
        }
    }
    if (port_get(&parent, goal) == -(1.0)) {
        return vec![];
    }
    reverse = vec![];
    cell = goal;
    while (cell != start) {
        port_push(cell, &mut reverse);
        cell = port_get(&parent, cell);
    }
    port_push(start, &mut reverse);
    result = vec![];
    i = (port_length(&reverse) - 1.0);
    while (i >= 0.0) {
        port_push(port_get(&reverse, i), &mut result);
        i -= 1.0;
    }
    return result;
}
